    "topic": "krithikal",
    "question": "\"കല - എത്ര ദീർഘം! സാധനാലഭ്യം! ആവു! ജീവിതമെത്ര ഹ്രസ്വതരം!\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടേതാണ്?",
