    "topic": "krithikal",
    "question": "\"മിത്രത്തെ ദോഷിപ്പാനായ്മിത്രം മിത്രമാക്കി പ്രത്യഹം ദുഷ്ടകർമ്മം ചെയ്തിടുന്നവൻ...\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടേതാണ്?",
