    "id": "kri_b4_18a",
    "topic": "krithikal",
    "question": "\"മാൻമാർക്ക് കൂട എന്ന ആ ശബ്ദം എത്രതവണ ഞാൻ ഉറക്കെ ആവർത്തിച്ചു എന്നു പറയാനാവില്...\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടേതാണ്?",
