    "question": "\"ആരൊരാളെൻ കുതിരയെക്കെട്ടുവാൻ ആരൊരാളതിൻ മാർഗ്ഗം മുടക്കുവാൻ\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടേതാണ്?",
