    "topic": "krithikal",
    "question": "\"മാപ്പു നൽകുകയെൻ പ്രിയ- മൈക്കലാഞ്ജലോ, മാപ്പ് മാപ്പിവർ ചെയ്യുന്നതെന്തെന്നി വര...\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടേതാണ്?",
