    "question": "\"കിട്ടും പണമെങ്കിലിപ്പോൾ മനുഷ്യർക്കു / ദുഷ്ടത കാട്ടുവാനൊട്ടും മടിയില്ല / കിട്ടിയതൊന്നും മതിയല്ല പിന്നെയും / കിട്ടിയാലും മതിയല്ല ദുരാഗ്രഹം\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടെ രചനയാണ്?",
