    "question": "\"മറക്കുവാൻ പറയാൻ എന്തെളുപ്പം - മണ്ണിൽ / പിറക്കാതിരിക്കലാണതിലെളുപ്പം\" - ഈ പ്രശസ്തമായ വരികൾ ആരുടെ രചനയാണ്?",
