    question: "താഴെ നൽകിയിരിക്കുന്നവയിൽ വ്യാകരണപരമായ വാക്യശുദ്ധിയുള്ള വാക്യം ഏത്? [LDC 2017]",
    options: ["സമയം ഏതാണ്ട് സന്ധ്യയോടടുത്തപ്പോൾ നാലഞ്ചോളം കൂട്ടുകാരുമായി അയാൾ വന്നു.", "സമയം ഏതാണ്ട് സന്ധ്യയോടടുത്തപ്പോൾ ഏകദേശം നാലഞ്ച് കൂട്ടുകാരുമായി അയാൾ വന്നു.", "സമയം ഏതാണ്ട് സന്ധ്യയോടടുത്തപ്പോൾ നാലഞ്ച് കൂട്ടുകാരുമായി അയാൾ വന്നു.", "സമയം ഏതാണ്ട് സന്ധ്യയോടടുത്തപ്പോൾ ഏകദേശം നാലഞ്ചോളം കൂട്ടുകാരുമായി അയാൾ വന്നു."],
    answer: 2,
    explanation: "'ഏകദേശം', 'നാലഞ്ച്' എന്നിവ ഒരേ വാക്യത്തിൽ ഒരുമിച്ച് ഉപയോഗിക്കുന്നത് പുനരുക്തിദോഷമാണ്. അതിനാൽ 'നാലഞ്ച് കൂട്ടുകാരുമായി' എന്ന് മാത്രം ഉപയോഗിക്കുന്നതാണ് ശരി. (Previous Exam: LDC 2017)"
